INSERT INTO categories (slug, name, description, position) VALUES
    ('teclados', 'Teclados', 'Mecânicos, hall effect e low profile para digitar e jogar com precisão.', 1),
    ('mouses', 'Mouses', 'Sensores de alta precisão e formatos pensados para longas sessões.', 2),
    ('headsets', 'Headsets', 'Áudio limpo para jogar, trabalhar e fazer chamadas.', 3),
    ('desk-mats', 'Desk mats', 'Superfícies de controle e velocidade para cobrir a mesa inteira.', 4),
    ('audio-e-video', 'Áudio e vídeo', 'Microfones e webcams para streams, aulas e reuniões.', 5),
    ('iluminacao', 'Iluminação', 'Light bars e luzes ambiente que cuidam dos seus olhos.', 6),
    ('ergonomia', 'Ergonomia', 'Braços articulados e suportes para uma postura melhor.', 7);
INSERT INTO products (sku, slug, name, short_description, description, price, compare_at_price, stock, art, accent_color, featured, category_id) VALUES
    ('DF-KB-001', 'anvil-75-hall-effect', 'Anvil 75 Hall Effect', 'Teclado 75% com switches magnéticos e ponto de acionamento ajustável.', 'Corpo em alumínio usinado, switches magnéticos com acionamento ajustável de 0,1 a 4,0 mm e rapid trigger para respostas instantâneas. Conexão USB-C, 2.4 GHz e Bluetooth.', 899.90, 1049.90, 18, 'KEYBOARD', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'teclados')),
    ('DF-KB-002', 'anvil-tkl-pro', 'Anvil TKL Pro', 'Tenkeyless com gaskets, PBT double-shot e hot-swap.', 'Montagem gasket com espuma em camadas para um som encorpado. Keycaps PBT double-shot que não desbotam e placa hot-swap para trocar switches sem solda.', 649.90, NULL, 25, 'KEYBOARD', '#3B82F6', TRUE, (SELECT id FROM categories WHERE slug = 'teclados')),
    ('DF-KB-003', 'anvil-65-wireless', 'Anvil 65 Wireless', 'Compacto 65% tri-mode para levar na mochila.', 'Layout 65% com setas dedicadas, três modos de conexão e até 200 horas de bateria com a iluminação desligada.', 499.90, 579.90, 32, 'KEYBOARD', '#A855F7', FALSE, (SELECT id FROM categories WHERE slug = 'teclados')),
    ('DF-KB-004', 'anvil-low-profile', 'Anvil Low Profile', 'Perfil baixo para quem digita o dia todo.', 'Altura de apenas 22 mm, switches low profile suaves e pareamento com até três dispositivos. Ideal para setups de trabalho.', 429.90, NULL, 40, 'KEYBOARD', '#10B981', FALSE, (SELECT id FROM categories WHERE slug = 'teclados')),
    ('DF-MS-001', 'ember-ultralight-x', 'Ember Ultralight X', 'Mouse sem fio de 49 g com sensor de 30.000 DPI.', 'Carcaça sem furos de apenas 49 g, sensor óptico de 30.000 DPI, polling de 4.000 Hz e pés de PTFE puro.', 549.90, 629.90, 22, 'MOUSE', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'mouses')),
    ('DF-MS-002', 'ember-ergo', 'Ember Ergo', 'Formato ergonômico para mãos médias e grandes.', 'Formato assimétrico com apoio para o polegar, sete botões programáveis e memória interna para cinco perfis.', 329.90, NULL, 35, 'MOUSE', '#3B82F6', FALSE, (SELECT id FROM categories WHERE slug = 'mouses')),
    ('DF-MS-003', 'ember-mini', 'Ember Mini', 'Simétrico e compacto para pegada claw e fingertip.', 'Formato simétrico compacto, 55 g, cabo paracord ultraflexível e switches ópticos com 100 milhões de cliques.', 219.90, 259.90, 50, 'MOUSE', '#F43F5E', FALSE, (SELECT id FROM categories WHERE slug = 'mouses')),
    ('DF-HS-001', 'quench-pro-wireless', 'Quench Pro Wireless', 'Headset sem fio com ANC e drivers de 50 mm.', 'Cancelamento de ruído ativo híbrido, drivers de grafeno de 50 mm e microfone destacável com filtro de ruído por IA. Até 60 horas de bateria.', 799.90, 949.90, 15, 'HEADSET', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'headsets')),
    ('DF-HS-002', 'quench-studio', 'Quench Studio', 'Fone aberto para mixagem e jogos com imagem estéreo ampla.', 'Design open-back com almofadas de veludo e cabo destacável. Palco sonoro amplo para identificar passos e mixar com fidelidade.', 599.90, NULL, 12, 'HEADSET', '#EAB308', FALSE, (SELECT id FROM categories WHERE slug = 'headsets')),
    ('DF-HS-003', 'quench-lite', 'Quench Lite', 'Leve, confortável e com som surround virtual 7.1.', 'Apenas 240 g, arco autoajustável e áudio 7.1 via software. Microfone flip-to-mute.', 279.90, 329.90, 45, 'HEADSET', '#3B82F6', FALSE, (SELECT id FROM categories WHERE slug = 'headsets')),
    ('DF-DM-001', 'slag-xxl-control', 'Slag XXL Control', 'Desk mat 90 × 40 cm com superfície de controle.', 'Tecido de trama fechada para mais controle, base de borracha natural antiderrapante e bordas costuradas que não desfiam.', 149.90, NULL, 60, 'DESKMAT', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'desk-mats')),
    ('DF-DM-002', 'slag-speed-glass', 'Slag Speed Glass', 'Mousepad de vidro temperado para deslize máximo.', 'Vidro temperado com acabamento microtexturizado: deslize rápido, consistente e fácil de limpar.', 269.90, 299.90, 20, 'DESKMAT', '#06B6D4', FALSE, (SELECT id FROM categories WHERE slug = 'desk-mats')),
    ('DF-DM-003', 'slag-felt-minimal', 'Slag Felt Minimal', 'Feltro de lã para um setup de trabalho clean.', 'Feltro de lã merino com base de cortiça. Visual minimalista e superfície macia para teclado e mouse.', 189.90, NULL, 30, 'DESKMAT', '#A3A3A3', FALSE, (SELECT id FROM categories WHERE slug = 'desk-mats')),
    ('DF-MC-001', 'bellows-usb-cardioid', 'Bellows USB Cardioid', 'Microfone USB-C cardioide com ganho e mute no corpo.', 'Cápsula de 25 mm, captação cardioide, controle de ganho, monitoramento sem latência e botão de mute por toque.', 459.90, 529.90, 24, 'MICROPHONE', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'audio-e-video')),
    ('DF-MC-002', 'bellows-dynamic-xlr', 'Bellows Dynamic XLR', 'Dinâmico XLR/USB que isola o ruído do ambiente.', 'Microfone dinâmico com saída dupla XLR e USB, ideal para ambientes sem tratamento acústico.', 699.90, NULL, 10, 'MICROPHONE', '#64748B', FALSE, (SELECT id FROM categories WHERE slug = 'audio-e-video')),
    ('DF-WC-001', 'crucible-4k', 'Crucible 4K', 'Webcam 4K com HDR e foco automático rápido.', 'Sensor de 1/2,5" com HDR, foco automático por detecção de fase e correção de luz baixa. Tampa de privacidade magnética.', 749.90, 849.90, 14, 'WEBCAM', '#FF6B2C', FALSE, (SELECT id FROM categories WHERE slug = 'audio-e-video')),
    ('DF-WC-002', 'crucible-1080', 'Crucible 1080', 'Full HD com microfones duplos para reuniões.', 'Imagem Full HD a 60 fps, microfones estéreo com redução de ruído e clipe universal.', 299.90, NULL, 38, 'WEBCAM', '#3B82F6', FALSE, (SELECT id FROM categories WHERE slug = 'audio-e-video')),
    ('DF-LT-001', 'spark-monitor-lightbar', 'Spark Monitor Light Bar', 'Light bar assimétrica que ilumina a mesa sem refletir na tela.', 'Feixe assimétrico, temperatura de cor de 2700 K a 6500 K, sensor de luz ambiente e controle sem fio.', 289.90, 339.90, 28, 'LIGHTBAR', '#FF6B2C', TRUE, (SELECT id FROM categories WHERE slug = 'iluminacao')),
    ('DF-LT-002', 'spark-ambient-duo', 'Spark Ambient Duo', 'Par de barras RGB para iluminar o fundo do setup.', 'Duas barras RGB endereçáveis com sincronização por música e cenas pelo app.', 249.90, NULL, 33, 'LIGHTBAR', '#A855F7', FALSE, (SELECT id FROM categories WHERE slug = 'iluminacao')),
    ('DF-ER-001', 'tong-single-arm', 'Tong Single Arm', 'Braço articulado a gás para monitores de até 32".', 'Mola a gás com ajuste de tensão, rotação de 360° e gestão de cabos integrada. Fixação por grampo ou furo.', 399.90, 459.90, 19, 'MONITOR_ARM', '#FF6B2C', FALSE, (SELECT id FROM categories WHERE slug = 'ergonomia')),
    ('DF-ER-002', 'tong-dual-arm', 'Tong Dual Arm', 'Braço duplo para setups com dois monitores.', 'Dois braços independentes a gás, ajuste fino de altura e inclinação, acabamento em alumínio anodizado.', 699.90, NULL, 9, 'MONITOR_ARM', '#64748B', TRUE, (SELECT id FROM categories WHERE slug = 'ergonomia')),
    ('DF-ER-003', 'tong-laptop-stand', 'Tong Laptop Stand', 'Suporte de alumínio que eleva o notebook à altura dos olhos.', 'Seis níveis de altura, dobrável e com borrachas que protegem o notebook e a mesa.', 159.90, 189.90, 55, 'MONITOR_ARM', '#A3A3A3', FALSE, (SELECT id FROM categories WHERE slug = 'ergonomia'));
